WITH joined AS (SELECT e.*, o.order_date, o.discount, o.channel FROM order_items e LEFT JOIN orders o ON e.order_id = o.id WHERE o.shipping_fee < 18) SELECT CASE WHEN quantity >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, SUM(discount) FILTER (WHERE channel = 'web') AS web_total_discount, BIT_OR(quantity) AS quantity_bit_or, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list FROM joined GROUP BY quantity_tier ORDER BY quantity_bit_or;
